+static int getNumWorkerWarps(Operation *op) {
+  int defaultNumWarps = gpu::lookupNumWarps(op);
+  auto mod = op->getParentOfType<ModuleOp>();
+  auto totalNumWarps = mod->getAttrOfType<IntegerAttr>("ttg.total-num-warps");
